// Distribuição equilibrada de letras, embaralhada de modo reprodutível.
const slots=Array.from({length:120},(_,i)=>i%5);let seed=20271023;
for(let i=slots.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[slots[i],slots[j]]=[slots[j],slots[i]];}
let cursor=0;const setCounters={'practice-a':0,'practice-b':0};
